import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"在应用开发中上传文件","description":"把 .zip 等文件拖入 AI 对话区、文件列表或编辑器，写入工程工作区并供 AI 助手读取。","frontmatter":{"title":"在应用开发中上传文件","description":"把 .zip 等文件拖入 AI 对话区、文件列表或编辑器，写入工程工作区并供 AI 助手读取。","kind":"how-to","status":"reviewed"},"headers":[],"relativePath":"zh/guide/upload-files.md","filePath":"zh/使用指南/在应用开发中上传文件.md"}'),d={name:"zh/guide/upload-files.md"};function i(l,t,n,s,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="在应用开发中上传文件" tabindex="-1">在应用开发中上传文件 <a class="header-anchor" href="#在应用开发中上传文件" aria-label="Permalink to &quot;在应用开发中上传文件&quot;">​</a></h1><p>在工程的<strong>应用开发</strong>里，除了让 AI 助手新建文件，也可以把本地文件直接放进工程工作区。<code>.zip</code>、<code>.tar.gz</code> 等压缩包按普通文件保存，不会自动解压；需要解压时告诉 AI 助手目标目录。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>已从平台公共入口登录，并打开目标工程的<strong>应用开发</strong>，工作区处于运行状态。AI 对话、编辑器和预览未就绪时，先按页面提示启动或修复工作区。</li><li>清楚文件要放在工程根目录还是某个子目录。上传只写入文件，不执行文件内容。</li></ul><h2 id="上传入口" tabindex="-1">上传入口 <a class="header-anchor" href="#上传入口" aria-label="Permalink to &quot;上传入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>操作</th><th>写入位置</th></tr></thead><tbody><tr><td>AI 对话区</td><td>把文件从本地文件管理器拖到对话输入区，或点击输入框左下角的<strong>附加文件</strong></td><td>当前工程根目录</td></tr><tr><td>AI 文件列表</td><td>把文件拖到左侧文件列表中的目录，或点击侧边栏的<strong>上传文件</strong></td><td>拖入的目录；按钮上传到工程根目录</td></tr><tr><td>编辑器</td><td>切到<strong>编辑器</strong>，把文件拖入左侧资源管理器</td><td>资源管理器中的当前目录</td></tr></tbody></table><p>图片（<code>.png</code>、<code>.jpg</code> 等）拖入对话区时会作为对话附件发给模型，不写入工作区；需要把图片放进工程时，请拖到文件列表或编辑器。</p><h2 id="确认结果" tabindex="-1">确认结果 <a class="header-anchor" href="#确认结果" aria-label="Permalink to &quot;确认结果&quot;">​</a></h2><ol><li>上传完成后，在文件列表确认文件出现在预期目录。</li><li>从对话区拖入的文件，输入框会自动插入 <code>@文件名</code>；可直接让 AI 助手读取、解压或修改。</li><li>文件没有出现时，查看上传提示：常见原因是超过大小限制、同名文件被跳过，或目标目录不属于当前工程。</li></ol><h2 id="限制与注意" tabindex="-1">限制与注意 <a class="header-anchor" href="#限制与注意" aria-label="Permalink to &quot;限制与注意&quot;">​</a></h2><ul><li>单个文件不超过 25 MB，单次上传合计不超过 100 MB；更大的压缩包请拆分后分批上传。</li><li>同名文件不会静默覆盖：从对话区拖入时跳过并提示；从文件列表上传时按冲突提示选择<strong>替换</strong>或<strong>跳过</strong>。</li><li>不支持直接拖入文件夹，请先打包上传或逐个上传。</li><li>上传的文件属于工程工作区，会随工程导出进入归档；不要把凭据、私钥等敏感文件放进工作区。</li><li>上传压缩包不会创建新工程；迁移已有工程请使用工程管理中的归档导入。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>文件进入工作区后，可以继续让 AI 助手读取或修改，也可以在编辑器里直接编辑、在预览中查看效果。</p><p>AI 对话与工作区的权限、访问方式见<a href="/induframe-docs/zh/guide/login">登录与退出</a>。</p>',14)])])}const p=a(d,[["render",i]]);export{u as __pageData,p as default};
